/* ===== Chat Layout ===== */
.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
    background: #1e1e2e;
    color: #cdd6f4;
    margin: -1rem -1.5rem;
}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 260px;
    min-width: 200px;
    background: #181825;
    border-right: 1px solid #313244;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

::deep .sidebar-title {
    padding: 1rem;
    margin: 0;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #a6adc8;
    border-bottom: 1px solid #313244;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
}

::deep .channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    padding: 0.6rem 1rem;
    cursor: pointer;
    transition: background 0.15s;
    border-left: 3px solid transparent;
}

::deep .channel-item:hover {
    background: #313244;
}

::deep .channel-item.active {
    background: #313244;
    border-left-color: #89b4fa;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
    color: #cdd6f4;
}

::deep .channel-desc {
    width: 100%;
    font-size: 0.75rem;
    color: #6c7086;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #f38ba8;
    color: #1e1e2e;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 7px;
    border-radius: 10px;
    min-width: 20px;
    text-align: center;
}

/* ===== Main Message Area ===== */
.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    transition: flex 0.2s;
}

.chat-main.full-width {
    flex: 1 1 100%;
}

.chat-main.empty-state {
    align-items: center;
    justify-content: center;
    color: #6c7086;
    font-size: 1.1rem;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
}

::deep .message-area-header {
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid #313244;
    background: #1e1e2e;
}

::deep .message-area-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #cdd6f4;
}

::deep .message-area-header p {
    margin: 0.2rem 0 0;
    font-size: 0.8rem;
    color: #6c7086;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
